 (function executeFixScript() {
    var tableName = "change_request";
    var fieldName = "category";

    gs.log("--- Cisco Secure Access Configuration Script ---");

    // STEP 1: Add category choice
    var newChoices = [
        { value: "CSA Configuration", label: "Cisco Secure Access", sequence: 400, inactive: false },
    ];

    newChoices.forEach(function (choice) {
        var gr = new GlideRecord("sys_choice");
        gr.addQuery("name", tableName);
        gr.addQuery("element", fieldName);
        gr.addQuery("value", choice.value);
        gr.query();

        if (!gr.next()) {
            var newGr = new GlideRecord("sys_choice");
            newGr.initialize();
            newGr.sys_scope = "global";
            newGr.name = tableName;
            newGr.element = fieldName;
            newGr.value = choice.value;
            newGr.label = choice.label;
            newGr.sequence = choice.sequence;
            newGr.inactive = choice.inactive;
            newGr.language = "en";
            newGr.insert();
            gs.log("Fix Script: Inserted choice " + choice.label);
        } else {
            gs.log("Fix Script: Choice " + choice.label + " already exists");
        }
    });

    // STEP 2: Create text field: u_destination_address
    var fieldText = new GlideRecord("sys_dictionary");
    fieldText.addQuery("name", tableName);
    fieldText.addQuery("element", "u_destination_address");
    fieldText.query();
    if (!fieldText.next()) {
        var newField = new GlideRecord("sys_dictionary");
        newField.initialize();
        newField.sys_scope = "global";
        newField.name = tableName;
        newField.element = "u_destination_address";
        newField.internal_type = "string";
        newField.column_label = "Destination Address";
        newField.max_length = 255;
        newField.mandatory = false;
        newField.insert();
        gs.log("Fix Script: Created text field u_destination_address");
    } else {
        gs.log("Fix Script: Field u_destination_address already exists");
    }

    // STEP 3: Create reference field: u_destination_list
    var fieldRef = new GlideRecord("sys_dictionary");
    fieldRef.addQuery("name", tableName);
    fieldRef.addQuery("element", "u_destination_list");
    fieldRef.query();
    if (!fieldRef.next()) {
        var newRef = new GlideRecord("sys_dictionary");
        newRef.initialize();
        newRef.sys_scope = "global";
        newRef.name = tableName;
        newRef.element = "u_destination_list";
        newRef.internal_type = "reference";
        newRef.reference = "u_cisco_secure_access_destination_list"; // adjust reference table
        newRef.column_label = "Destination List";
        newRef.mandatory = false;
        newRef.insert();
        gs.log("Fix Script: Created reference field u_destination_list");
    } else {
        gs.log("Fix Script: Field u_destination_list already exists");
    }

    // STEP 4: Create the UI Policy record
    var policyExists = new GlideRecord('sys_ui_policy');
    policyExists.addQuery('short_description', 'Show Cisco CSA fields');
    policyExists.addQuery('table', 'change_request');
    policyExists.query();

    var policyId;
    if (!policyExists.next()) {
        var policy = new GlideRecord('sys_ui_policy');
        policy.initialize();
        policy.sys_scope = "global";
        policy.short_description = 'Show Cisco CSA fields';
        policy.table = 'change_request';
        policy.active = true;
        policy.reverse_if_false = true;
        policy.on_load = true;
        policy.conditions = 'category=CSA Configuration';
        policyId = policy.insert();
        gs.log("Fix Script: Created UI Policy with ID: " + policyId);
    } else {
        policyId = policyExists.sys_id.toString();
        gs.log("Fix Script: UI Policy already exists with ID: " + policyId);
    }

    // STEP 5: Create UI Policy Action for u_destination_address
    var action1Exists = new GlideRecord('sys_ui_policy_action');
    action1Exists.addQuery('ui_policy', policyId);
    action1Exists.addQuery('field', 'u_destination_address');
    action1Exists.query();

    if (!action1Exists.next()) {
        var action1 = new GlideRecord('sys_ui_policy_action');
        action1.initialize();
        action1.sys_scope = "global";
        action1.ui_policy = policyId;
        action1.field = 'u_destination_address';
        action1.visible = true;
        action1.mandatory = true;
        action1.disabled = false;
        action1.insert();
        gs.log("Fix Script: Created UI Policy Action for u_destination_address");
    }

    // STEP 6: Create UI Policy Action for u_destination_list
    var action2Exists = new GlideRecord('sys_ui_policy_action');
    action2Exists.addQuery('ui_policy', policyId);
    action2Exists.addQuery('field', 'u_destination_list');
    action2Exists.query();

    if (!action2Exists.next()) {
        var action2 = new GlideRecord('sys_ui_policy_action');
        action2.initialize();
        action2.sys_scope = "global";
        action2.ui_policy = policyId;
        action2.field = 'u_destination_list';
        action2.visible = true;
        action2.mandatory = true;
        action2.disabled = false;
        action2.insert();
        gs.log("Fix Script: Created UI Policy Action for u_destination_list");
    }

    // STEP 7: Add fields to form layout
    function addToFormLayout(fieldName, label) {
        var section = new GlideRecord("sys_ui_section");
        section.addQuery("name", tableName + ".default"); // default form
        section.query();
        if (section.next()) {
            var element = new GlideRecord("sys_ui_element");
            element.addQuery("element", fieldName);
            element.addQuery("sys_ui_section", section.sys_id);
            element.query();
            if (!element.next()) {
                element.initialize();
                element.name = tableName;
                element.element = fieldName;
                element.position = 500;
                element.sys_ui_section = section.sys_id;
                element.insert();
                gs.log("📋 Added " + label + " to form layout.");
            }
        }
    }
    addToFormLayout("u_destination_address", "Destination Address");
    addToFormLayout("u_destination_list", "Destination List");

    gs.log("✅ Fix Script completed successfully.");
})();
